}

getSelectUrl=(num)=>{
	 if(dict.groupNum==0){
	  	   login("❗️请先选择分组")
	  	   return
	 	}
	 dict.selectNum=num
	 msg="💠已选择  "+source.loginUi()[7+num].name
	 source.setVariable(JSON.stringify(dict))
  login(msg)
}

choice=(type)=>{
